    {
      "id": "capstone",
      "number": "05",
      "name": "Integrated Systems Capstone",
      "tagline": "Synthesizing Integration, Modularity, Optimization, and Scalability under real-world constraints",
      "color": "#f472b6",
      "summary": "Real engineering problems never arrive labeled 'This is a Scalability question'. A caching fix breaks consistency; a modular microservice split blows up tail latency; an integration retry triggers a cascading outage.",
      "mentalModel": "Every architectural decision shifts complexity rather than destroying it. Principal engineering wisdom is knowing *where* to place the complexity so it stays observable, reversible, and proportional to your team's operational maturity.",
      "lessons": [
        {
          "id": "cap-1",
          "title": "Cross-Pillar Trade-offs & Principal Decision Framework",
          "duration": "30 min",
          "knowledge": [
            "Tension 1 (Modularity vs Optimization): splitting into fine-grained network services improves team autonomy but replaces sub-microsecond function calls with millisecond serialization and tail-latency amplification.",
            "Tension 2 (Integration vs Scalability): synchronous request-reply preserves immediate invariants but couples availability and limits burst absorption compared to async outbox pipelines.",
            "Tension 3 (Optimization vs Consistency): aggressive caching and read replicas slash DB load and latency, but introduce stale-read windows and cache invalidation races.",
            "Reversibility Matrix (Two-Way vs One-Way Doors): invest deep upfront design only in hard-to-reverse decisions (data ownership boundaries, shard keys, public contracts, consistency guarantees)."
          ],
          "wisdom": [
            "When diagnosing an incident, trace in reverse order of layers: Load/Traffic -> Edge/Gateway -> App Threads/Pools -> Cache -> Database/Locks -> Downstream Integrations.",
            "Never adopt a pattern just because a hyperscaler blogged about it—Google/Netflix solve problems at 10,000-engineer and million-QPS scale where the cost of coordination differs completely from yours.",
            "Write RFCs that explicitly list 'What breaks first at 10x load?' and 'How do we disable/roll back this integration in 60 seconds?'"
          ],
          "tradeoffs": [
            {
              "option": "Boring Monolith + Outbox + Read Replica + Redis",
              "pros": "Handles 10k-50k+ RPS easily, small team velocity, high observability, minimal distributed failure modes.",
              "cons": "Requires modular discipline inside repo; less suited for 200+ engineers sharing one deploy pipeline.",
              "whenToUse": "Default baseline architecture until concrete bottlenecks prove otherwise."
            },
            {
              "option": "Distributed Event-Driven + Sharded Services",
              "pros": "Extreme scale, independent fault/deploy domains, multi-region resilience.",
              "cons": "High operational floor (meshes, tracing, schema registries, distributed debugging, SRE staffing).",
              "whenToUse": "High-scale, multi-team enterprises with mature platform engineering."
            }
          ],
          "antiPatterns": [
            "Resume-Driven Architecture: adopting Kafka + 15 microservices + GraphQL federation for 50 requests/second.",
            "Local Optimization Bias: speeding up one service 10x only to discover it now overwhelms the unscaled downstream payment partner.",
            "Missing Ownership: 'shared' infrastructure or queues that belong to everyone and therefore no one during a 2 AM outage."
          ],
          "heuristic": "Optimize for reversibility, debuggability at 2 AM, and alignment with team topology—not diagram elegance.",
          "sources": [
            {
              "title": "MonolithFirst",
              "author": "Martin Fowler",
              "url": "https://martinfowler.com/bliki/MonolithFirst.html"
            },
            {
              "title": "Metastable Failures in Distributed Systems (HotOS 2021)",
              "author": "Bronson, Aghayev, Charapko & Zhu",
              "url": "https://charap.co/metastable-failures-in-distributed-systems/"
            },
            {
              "title": "The Tail at Scale (CACM, 2013)",
              "author": "Jeffrey Dean & Luiz André Barroso (Google)",
              "url": "https://research.google/pubs/the-tail-at-scale/"
            },
            {
              "title": "Designing Data-Intensive Applications",
              "author": "Martin Kleppmann",
              "url": "https://dataintensive.net/"
            }
          ]
        }
      ]
    }
